require_once '../config/database.php';require_once '../config/auth.php';require_once '../eventos/helpers.php';$u=requireAuth();requireCsrf();if(!usuarioTemAcessoEmpresa($conn,$u['id'],2,$u['perfil']))jsonResponse(false,'Sem acesso.',[],403);$in=readJson();$sid=(int)($in['servico_id']??0);$mao=(float)($in['valor_mao_obra']??0);$pecas=(float)($in['valor_pecas']??0);$desc=trim($in['descricao']??'');if(!$sid||$mao<0||$pecas<0)jsonResponse(false,'Dados inválidos.',[],400);$total=$mao+$pecas;$conn->begin_transaction();try{$s=$conn->prepare('SELECT protocolo FROM servicos WHERE id=? AND empresa_id=2 FOR UPDATE');$s->bind_param('i',$sid);$s->execute();$serv=$s->get_result()->fetch_assoc();if(!$serv)throw new RuntimeException('Serviço não encontrado.');$codigo='ORC-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$token=bin2hex(random_bytes(32));$x=$conn->prepare("INSERT INTO orcamentos(empresa_id,servico_id,codigo,descricao,valor_mao_obra,valor_pecas,valor_total,status,token_publico,enviado_em) VALUES(2,?,?,?,?,?,?, 'ENVIADO',?,NOW())");$x->bind_param('issddds',$sid,$codigo,$desc,$mao,$pecas,$total,$token);$x->execute();$id=(int)$conn->insert_id;$up=$conn->prepare("UPDATE servicos SET status='AGUARDANDO_APROVACAO',valor_estimado=? WHERE id=?");$up->bind_param('di',$total,$sid);$up->execute();$h=$conn->prepare("INSERT INTO servicos_historico(servico_id,usuario_id,status_anterior,status_novo,observacao) VALUES(?,?,'AGUARDANDO_ORCAMENTO','AGUARDANDO_APROVACAO','Orçamento enviado')");$h->bind_param('ii',$sid,$u['id']);$h->execute();criarEventoENotificar($conn,2,$u['id'],'Orçamento '.$codigo,'Orçamento de R$ '.number_format($total,2,',','.').' enviado.','ATENCAO','SERVICO',$sid,'ORCAMENTO_ENVIADO:'.$id,'ORCAMENTOS','ORCAMENTO_ENVIADO');registrarAuditoria($conn,$u['id'],2,'CRIAR_ORCAMENTO','ORCAMENTO',$id,$codigo);enfileirarSheets($conn,2,'ORCAMENTO','ORCAMENTO',$id);$conn->commit();jsonResponse(true,'Orçamento criado.',['id'=>$id,'codigo'=>$codigo,'token_publico'=>$token,'total'=>$total]);}catch(Throwable $e){$conn->rollback();jsonResponse(false,$e->getMessage(),[],400);}
